package app.noir.mobile;
import android.app.*;
import android.widget.*;
import android.view.*;
import org.json.*;
import java.util.*;
import java.time.*;

final class PremiumLibrary {
 final MainActivity a;String historyView="Collection",month="All time",status="All",collection="All",type="All",sort="Recent";int diaryLimit=60;
 PremiumLibrary(MainActivity activity){a=activity;}
 void chips(String[] values,String chosen,java.util.function.Consumer<String> action){HorizontalScrollView scroll=new HorizontalScrollView(a);LinearLayout row=new LinearLayout(a);scroll.setHorizontalScrollBarEnabled(false);scroll.addView(row);a.body.addView(scroll);for(String value:values){Button b=a.button(value,()->action.accept(value),value.equals(chosen));row.addView(b,new LinearLayout.LayoutParams(-2,a.dp(46)));}}
 static String month(JSONObject v){long at=DataStore.date(v.optString("watchedAt"));return Instant.ofEpochMilli(at).atZone(ZoneId.systemDefault()).toLocalDate().toString().substring(0,7);}
 void history(){chips(new String[]{"Collection","Diary"},historyView,v->{historyView=v;a.render();});List<JSONObject> records=new ArrayList<>();TreeSet<String> months=new TreeSet<>(Comparator.reverseOrder());for(JSONObject i:DataStore.objects(a.data.items()))for(JSONObject v:DataStore.objects(i.optJSONArray("viewings"))){JSONObject r=DataStore.copy(v);DataStore.put(r,"item",i);records.add(r);months.add(month(v));}
  List<String> choices=new ArrayList<>();choices.add("All time");choices.addAll(months);Spinner picker=new Spinner(a);picker.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,choices));picker.setSelection(Math.max(0,choices.indexOf(month)));a.body.addView(picker);picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View view,int n,long id){String value=choices.get(n);if(!month.equals(value)){month=value;diaryLimit=60;a.render();}}});
  records.removeIf(v->!month.equals("All time")&&!month(v).equals(month));records.sort((x,y)->Long.compare(DataStore.date(y.optString("watchedAt")),DataStore.date(x.optString("watchedAt"))));Set<String> titles=new HashSet<>();double seconds=0;int rewatches=0;for(JSONObject r:records){JSONObject i=r.optJSONObject("item");titles.add(i.optString("group"));seconds+=i.optDouble("duration");long at=DataStore.date(r.optString("watchedAt"));if(DataStore.objects(i.optJSONArray("viewings")).stream().anyMatch(v->DataStore.date(v.optString("watchedAt"))<at))rewatches++;}
  a.paragraph(records.size()+" viewings · "+titles.size()+" titles · "+rewatches+" rewatches\n"+String.format(Locale.ROOT,"%.1f h known runtime",seconds/3600));
  if(historyView.equals("Diary")){String day="";int shown=0;for(JSONObject r:records){if(++shown>diaryLimit)break;JSONObject i=r.optJSONObject("item");String date=Instant.ofEpochMilli(DataStore.date(r.optString("watchedAt"))).atZone(ZoneId.systemDefault()).toLocalDate().toString();if(!date.equals(day)){a.heading(date);day=date;}a.body.addView(diaryCard(i,r));}if(records.isEmpty())a.paragraph("No viewings in this month.");if(records.size()>diaryLimit)a.body.addView(a.button("Load more viewings",()->{diaryLimit+=60;a.render();},false));return;}
  chips(new String[]{"All","Movies","Shows"},type,v->{type=v;a.render();});chips(new String[]{"Recent","A–Z"},sort,v->{sort=v;a.render();});
  chips(new String[]{"All","Watching","Planned","Finished","Dropped","Unavailable"},status,v->{status=v;a.render();});List<List<JSONObject>> groups=a.groups();groups.removeIf(g->type.equals("Movies")&&!g.get(0).optBoolean("movie")||type.equals("Shows")&&g.get(0).optBoolean("movie"));groups.removeIf(g->g.stream().noneMatch(i->DataStore.watched(i)||MainActivity.position(i)>0)&&!g.get(0).optString("status").equals("Dropped")&&!g.get(0).optString("status").equals("Finished"));groups.removeIf(g->!status.equals("All")&&(status.equals("Unavailable")?g.stream().anyMatch(a::playable):!label(g).equals(status)));if(sort.equals("Recent"))groups.sort((x,y)->Long.compare(MainActivity.recent(y),MainActivity.recent(x)));a.grid(groups,a.body);
 }
 android.view.View diaryCard(JSONObject i,JSONObject record){LinearLayout row=new LinearLayout(a);row.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));row.setBackground(MainActivity.bg(MainActivity.PANEL,a.dp(12)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,a.dp(10));row.setLayoutParams(lp);row.addView(a.poster(i,true),new LinearLayout.LayoutParams(a.dp(64),a.dp(94)));LinearLayout info=a.column();LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,-2,1);ip.setMargins(a.dp(14),0,0,0);row.addView(info,ip);info.addView(a.text(i.optString("title"),17,MainActivity.WHITE));info.addView(a.text(MainActivity.episode(i)+" · "+Instant.ofEpochMilli(DataStore.date(record.optString("watchedAt"))).atZone(ZoneId.systemDefault()).toLocalTime().withSecond(0).withNano(0),12,MainActivity.MUTED));info.addView(a.text(record.optString("source"),11,MainActivity.MUTED));JSONObject review=i.optJSONObject("review");if(review!=null&&review.optInt("rating")>0)info.addView(a.text(String.join("",Collections.nCopies(review.optInt("rating"),"★")),15,MainActivity.GOLD));info.addView(a.text("Details · rating · comments",12,MainActivity.GOLD));row.setOnClickListener(v->a.options(i));return row;}
 String label(List<JSONObject> group){String manual=group.get(0).optString("status");if(!manual.isEmpty()&&!manual.equals("Automatic"))return manual;if(group.stream().allMatch(DataStore::watched))return "Finished";return group.stream().anyMatch(i->DataStore.watched(i)||MainActivity.position(i)>0)?"Watching":"Planned";}
 void status(JSONObject i){String[] labels={"Automatic","Watching","Planned","Finished","Dropped"};new AlertDialog.Builder(a).setTitle("Viewing status").setItems(labels,(d,n)->{JSONObject op=a.data.operation(i.optString("id"),"status");DataStore.put(op,"status",labels[n]);a.data.queue(op);a.data.syncSoon();a.render();}).show();}
 boolean member(JSONObject i,String name){JSONArray members=i.optJSONArray("collections");if(members!=null)for(int n=0;n<members.length();n++)if(members.optString(n).equals(name))return true;return false;}
 void collections(JSONObject i){JSONArray list=a.data.settings().optJSONArray("collections");List<String> names=new ArrayList<>();if(list!=null)for(int n=0;n<list.length();n++)names.add(list.optString(n));names.add("+ New collection");new AlertDialog.Builder(a).setTitle("Save to collection").setItems(names.toArray(new String[0]),(d,n)->{if(n==names.size()-1){EditText input=new EditText(a);input.setHint("Collection name");new AlertDialog.Builder(a).setTitle("New collection").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Create",(dialog,w)->change(i,input.getText().toString().trim(),true)).show();}else change(i,names.get(n),!member(i,names.get(n)));}).show();}
 void change(JSONObject i,String name,boolean value){if(name.isEmpty()||name.length()>60||name.equals("All")||name.equals("My List")){a.toast("Use a name with 1–60 characters.");return;}JSONObject op=a.data.operation(i.optString("id"),"collection");DataStore.put(op,"name",name);DataStore.put(op,"value",value);a.data.queue(op);a.data.syncSoon();a.render();a.toast(value?"Saved to "+name:"Removed from "+name);}
 void match(JSONObject i){LinearLayout panel=a.column();panel.setPadding(a.dp(20),0,a.dp(20),0);String[] labels={"Title","Year","IMDb ID (optional)","Season","Episode"},keys={"title","year","imdb","season","episode"};EditText[] inputs=new EditText[5];for(int n=0;n<5;n++){EditText input=new EditText(a);input.setHint(labels[n]);input.setText(i.optString(keys[n]));panel.addView(input);inputs[n]=input;}CheckBox whole=new CheckBox(a);whole.setText("Apply title and season offset to the whole show");whole.setChecked(!i.optBoolean("movie"));panel.addView(whole);ScrollView scroll=new ScrollView(a);scroll.addView(panel);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Correct match · history stays intact").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String title=inputs[0].getText().toString().trim(),imdb=inputs[2].getText().toString().trim();int year=Integer.parseInt(inputs[1].getText().toString()),season=Integer.parseInt(inputs[3].getText().toString()),episode=Integer.parseInt(inputs[4].getText().toString());if(title.isEmpty()||title.length()>200||year<0||year>2100||season<0||season>1000||episode<0||episode>10000||!imdb.isEmpty()&&!imdb.matches("tt[0-9]+"))throw new IllegalArgumentException();for(JSONObject other:DataStore.objects(a.data.items()))if(other.optString("group").equals(i.optString("group"))){if(whole.isChecked()&&other.optInt("season")+season-i.optInt("season")<0)throw new IllegalArgumentException();if(!whole.isChecked()&&!other.optString("id").equals(i.optString("id"))&&other.optInt("season")==season&&other.optInt("episode")==episode)throw new IllegalArgumentException();}JSONObject op=a.data.operation(i.optString("id"),"match");DataStore.put(op,"title",title);DataStore.put(op,"year",year);DataStore.put(op,"imdb",imdb);DataStore.put(op,"season",season);DataStore.put(op,"episode",episode);DataStore.put(op,"value",whole.isChecked());a.data.queue(op);a.data.syncSoon();dialog.dismiss();a.render();a.toast("Correction saved. Syncs with your PC.");}catch(Exception e){inputs[0].setError("Check the fields and episode numbers.");}}));dialog.show();}
 void filter(){List<String> names=new ArrayList<>(Arrays.asList("All","My List"));JSONArray list=a.data.settings().optJSONArray("collections");if(list!=null)for(int n=0;n<list.length();n++)names.add(list.optString(n));chips(names.toArray(new String[0]),collection,v->{collection=v;a.render();});}
 void extras(){if(a.data.lastSync()>0)a.paragraph("Last synced "+Instant.ofEpochMilli(a.data.lastSync()).atZone(ZoneId.systemDefault()).toLocalDateTime().withSecond(0).withNano(0));JSONArray queue=a.data.playQueue();if(queue.length()>0){a.heading("Your play queue");for(int n=0;n<queue.length();n++){JSONObject i=a.data.item(queue.optString(n));if(i==null)continue;a.body.addView(a.button(i.optString("title")+" · "+MainActivity.episode(i)+" · Options",()->new AlertDialog.Builder(a).setItems(new String[]{"Play","Remove from queue","Move earlier","Move later"},(d,w)->{if(w==0)a.play(i,false);else{if(w==1)a.data.consumeVideo(i.optString("id"));else a.data.moveVideo(i.optString("id"),w==2?-1:1);a.render();}}).show(),false));}}
  List<List<JSONObject>> added=a.groups();added.removeIf(g->g.stream().noneMatch(i->DataStore.date(i.optString("addedAt"))>0));added.sort((x,y)->Long.compare(y.stream().mapToLong(i->DataStore.date(i.optString("addedAt"))).max().orElse(0),x.stream().mapToLong(i->DataStore.date(i.optString("addedAt"))).max().orElse(0)));if(!added.isEmpty()){a.heading("Recently added");a.grid(added.subList(0,Math.min(6,added.size())),a.body);}
  JSONObject schedules=a.data.settings().optJSONObject("schedules");if(schedules!=null){List<JSONObject> upcoming=new ArrayList<>();for(List<JSONObject> g:a.groups())for(JSONObject ep:DataStore.objects(schedules.optJSONArray(g.get(0).optString("group")))){long at=DataStore.date(ep.optString("airsAt"));if(at>System.currentTimeMillis()&&at<System.currentTimeMillis()+30L*86400000){JSONObject e=DataStore.copy(ep);DataStore.put(e,"show",g.get(0));upcoming.add(e);}}upcoming.sort(Comparator.comparingLong(i->DataStore.date(i.optString("airsAt"))));if(!upcoming.isEmpty()){a.heading("Coming up");a.paragraph("Announced dates from your cached TVmaze information.");for(JSONObject ep:upcoming.subList(0,Math.min(8,upcoming.size()))){JSONObject show=ep.optJSONObject("show");a.body.addView(a.button(show.optString("title")+" · "+MainActivity.episode(ep)+" · "+Instant.ofEpochMilli(DataStore.date(ep.optString("airsAt"))).atZone(ZoneId.systemDefault()).toLocalDate(),()->a.open(show),false));}}}
 }
}
